\begin{lemma}\label{lem:ic-meas-side-info}
Consider a state two-design on $B$, i.e., a set of rank-one projectors $\{P_z\}_{z \in \{1, \dots, t\}}$ such that $\frac{1}{t} \sum_{z=1}^t P_z \otimes P_z = \frac{2 P^{\mathrm{sym}}}{d_B (d_B+1)}$, where $P^{\mathrm{sym}}$ denotes the projector onto the symmetric subspace of $B \otimes B$. Let $\mathcal{M}_B$ be the measurement defined as
\begin{align}
\mathcal{M}_B(X) = \sum_{z} \frac{d_B}{t} \cdot\mathrm{Tr}\big[P_z X\big] |z\rangle\langle z|,
\end{align}
and $\xi_{AB}$ be a Hermitian matrix on $A\otimes B$. Then, we have that
\begin{align}
\| (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \|_1\geq \frac{1}{d_B^2 (d_B+1)} \| \xi_{AB} \|_{1}.
\end{align}
\end{lemma}

\begin{proof}
For any full rank quantum state $\sigma_{A}$, we have by a H\"older type inequality for $\sigma$-weighted Schatten norms that (see, e.g., \cite{OLKIEWICZ1999246} or \cite{beigi13})
\begin{align}
\| (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \|_1 \geq  \frac{\left\| \sigma_{A}^{-1/4} (\mathcal{I}_{A} \otimes \mathcal{M})(\xi_{AB}) \sigma_{A}^{-1/4} \right\|^2_{2}}{\left\| \sigma_{A}^{-1/2} (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \sigma_{A}^{-1/2} \right\|_{\infty}}.
\end{align}
For example, the above inequality can be obtained using \cite[Corollary 3]{beigi13} with the operator $\sigma_{A}^{-1/2} (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \sigma_{A}^{-1/2}$, weight $\sigma$, and $p_\theta = 2$, $\theta = 1/2$, $p_0 = 1$, $p_1 = \infty$. We note that this particular H\"older type inequality for $\sigma$-weighted norms is elementary and follows easily from the usual H\"older inequality, but one way of potentially improving the dimension dependence in Lemma~\ref{lem:ic-meas-side-info} might be to use another H\"older inequality, in particular the $(1,4)$ inequality.

Henceforth, we abbreviate $d\equiv d_B$. To further bound the numerator, letting $\tilde{\xi}_{AB}:=\sigma_{A}^{-1/4} \xi_{AB} \sigma_{A}^{-1/4}$ we get
\begin{align}
\| (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\tilde{\xi}_{AB}) \|^2_{2}
&= \left\| \sum_{z} \frac{d}{t} |z\rangle \langle z| \otimes  \mathrm{Tr}_{B}\left[(1_{A} \otimes P_z) \tilde{\xi}_{AB}\right] \right\|_2^2 \\
&= \sum_{z}  \frac{d^2}{t^2} \mathrm{Tr}\left[\mathrm{Tr}_{B}\left[(1_{A} \otimes P_z) \tilde{\xi}_{AB}\right] \otimes \mathrm{Tr}_{\bar{B}}\left[(1_{\bar{A}} \otimes P_z) \tilde{\xi}_{\bar{A}\bar{B}}\right]^{\dagger} F_{A\bar{A}} \right] \\
&= \sum_{z} \frac{d^2}{t^2} \mathrm{Tr}\left[\left(\left((1_{A} \otimes P_z) \tilde{\xi}_{AB}\right) \otimes \left((1_{\bar{A}} \otimes P_z) \tilde{\xi}_{\bar{A}\bar{B}}\right)^{\dagger}\right)\left(F_{A\bar{A}} \otimes1_{B\bar{B}}\right)\right] \\
&= \frac{d^2}{t^2} \mathrm{Tr}\left[\left(\tilde{\xi}_{AB} \otimes \tilde{\xi}_{\bar{A}\bar{B}}^{\dagger}\right)\left(\sum_{z} (1_{A\bar{A}} \otimes P_z \otimes P_{z})\right)\left(F_{A\bar{A}} \otimes1_{B \bar{B}}\right)\right] \\
&= \frac{1}{t} \frac{d^2}{d(d+1)} \mathrm{Tr}\left[\left(\tilde{\xi}_{AB} \otimes \tilde{\xi}_{\bar{A}\bar{B}}^{\dagger}\right) (1_{A\bar{A}} \otimes (1_{B\bar{B}} + F_{B\bar{B}}))\left(F_{A\bar{A}} \otimes1_{B \bar{B}}\right)\right] \\
&= \frac{1}{t} \frac{d^2}{d(d+1)} \Big(\underbrace{\mathrm{Tr}\left[\tilde{\xi}_{A} \tilde{\xi}_{A}^{\dagger}\right]}_{\geq 0} + \underbrace{\mathrm{Tr}\left[\tilde{\xi}_{AB} \tilde{\xi}_{AB}^{\dagger}\right]}_{=\left\|\tilde{\xi}_{AB}\right\|_2^2} \Big) \\
&\geq \frac{1}{t}\frac{d^2}{d^2 (d+1)} \| \xi_{AB} \|^2_{1} ,
\end{align}
where $F$ denotes the swap operator (as defined in Section \ref{sec:notation}) and in the last step used the H\"older inequality (see, e.g., \cite{bhatia97})
\begin{align}
\left\|\xi_{AB}\right\|_1=\left\|\sigma^{1/4}\sigma^{-1/4}\xi_{AB}\sigma^{-1/4}\sigma^{1/4}\right\|_1\leq\left\|\sigma^{1/4}\otimes1_B\right\|_4\left\|\sigma_A^{-1/4}\xi_{AB}\sigma_A^{-1/4}\right\|_2\left\|\sigma^{1/4}\otimes1_B\right\|_4\leq\sqrt{d}\left\|\tilde{\xi}_{AB}\right\|_2.
\end{align}
For further bounding the denominator we write
\begin{align}
\left\| \sigma_{A}^{-1/2} (\mathcal{I}_{A} \otimes \mathcal{M}_B)(\xi_{AB}) \sigma_{A}^{-1/2} \right\|_\infty
&= \max_{z} \frac{d}{t} \left\| \mathrm{Tr}_{B}\left[(1_{A} \otimes P_z) \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2}\right]\right\|_\infty \\
&\leq \frac{d}{t} \max_{\ket{\phi}_{A}, \ket{\psi}_{B}} \bra{\phi}_{A} \otimes \bra{\psi}_{B} \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2} \ket{\phi}_{A} \otimes \ket{\psi}_{B} \\
&\leq \frac{d}{t} \left\| \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2} \right\|_\infty,
\end{align}
where we used the fact that $P_z$ is a rank 1 projector. Now, observe that for any $\xi_{AB}$, there exists a $\sigma_A$ of unit trace such that
\begin{align}
\frac{\sqrt{\xi_{AB} \xi_{AB}^{\dagger}}}{\| \xi_{AB} \|_{1}} \preceq d\cdot\sigma_{A} \otimes1_{B}.
\end{align}
This just follows from, e.g., \cite[Lemma B.6]{bertachristandl11}, where it is shown that we can in fact choose\footnote{By a continuity argument $\sigma_A$ can be assumed to have full rank.}
\begin{align}
\sigma_{A} = \| \xi_{AB} \|_{1}^{-1}\cdot\mathrm{Tr}_{B}\left[\sqrt{\xi_{AB} \xi_{AB}^{\dagger}}\right].
\end{align}
As a result, we have
\begin{align}
\sqrt{\xi_{AB} \xi_{AB}^{\dagger}} \preceq d\| \xi_{AB} \|_{1}\cdot\sigma_{A} \otimes1_{B}.
\end{align}
As $\xi_{AB}$ is Hermitian, we can decompose it into the positive and negative part $\xi_{AB} = P - Q$ with $P$ and $Q$ positive semidefinite and $PQ = 0$, then $\sqrt{\xi_{AB} \xi_{AB}^{\dagger}} = P + Q$ and so $-\sqrt{\xi_{AB} \xi_{AB}^{\dagger}} \preceq \xi_{AB} \preceq \sqrt{\xi_{AB} \xi_{AB}^{\dagger}}$. Thus, we get
\begin{align}
- d_{B} \| \xi_{AB} \|_1\cdot\sigma_{A} \otimes1_{B} \preceq \xi_{AB} \preceq d_{B} \| \xi_{AB} \|_1 \cdot\sigma_{A} \otimes1_{B},
\end{align}
and we find $\| \sigma_{A}^{-1/2} \xi_{AB} \sigma_{A}^{-1/2} \|_{\infty} \leq d\| \xi_{AB} \|_1$. This concludes the proof.
\end{proof}

