\rho_{A|z}:= \frac{\mathrm{Tr}_{Z}\Big[\rho_{AZ} \left(1_{A} \otimes \ket{z}\bra{z}\right)\Big]}{\mathrm{Tr}\Big[\rho_{AZ} \left(1_{A} \otimes \ket{z}\bra{z}\right)\Big]}.
\end{align}
We simply write $\exc{z_{1}^{m}}{\cdot}$ for the expectation over the choices of $z_1^m$ and the distribution will be clear from the context.

