That is, in the language of quantum information theory we are maximizing over a subset of the so-called {\it separable quantum states}\,---\,where the latter is defined on $A\otimes B$ as
\begin{align}
\text{Sep}(A:B)=\left\{\sum_{i\in I}p_iW_A^i \otimes W_B^i: W_A^i \succeq 0, W_B^i \succeq 0, \mathrm{Tr}\left[W_A^i\right]=\mathrm{Tr}\left[W_B^i\right] = 1,p_i\geq0,\sum_{i\in I}p_i=1\right\}.
\end{align}
Recall that matrices $W_A\in\mathcal{S}^+_A$ are called quantum states on system $A$\,---\,and similarly for bipartite states on $A\otimes B$.

In the following, we introduce some notation that is standard in quantum information theory. A $d_A$-dimensional quantum system (or in short {\it system}) is given by an inner product space $\mathbb{C}^{d_A}$ and denoted by $A$. {\it Quantum states} (or in short {\it states}) on $A$ are matrices\footnote{Here and henceforth we use the symbol $:=$ as {\it equal by definition}.}
\begin{align}
\text{$W_A\in\mathcal{S}_A:=\mathbb{C}^{d_A\times d_A}$ with $\mathrm{Tr}[W_A]=1$ and $W_A\succeq0$,}
\end{align}
where $\succeq$ denotes the operator (Loewner) order. Quantum states of rank one are called {\it pure} and can be written as $W_A=\ket{\psi}\bra{\psi}_A$, where $\ket{\psi}_A\in\mathbb{C}^{d_A}$ and $\ket{\psi}\bra{\psi}_A\in\mathcal{S}_A$ denotes the rank-one projector on the vector $\ket{\psi}_A$.

A {\it bipartite system} $AB:=A\otimes B$ is given by an inner product space $\mathbb{C}^{d_A}\otimes\mathbb{C}^{d_B}$, where $\otimes$ denotes the Kronecker tensor product. Correspondingly, states on $AB$ are matrices $W_{AB}\in\mathcal{S}_A\otimes\mathcal{S}_B$ with $\mathrm{Tr}[W_{AB}]=1$ and $W_{AB}\succeq0$. {\it Separable states} are states on $AB$ that are in the convex hull of product states $W_A\otimes W_B$, with $W_A$ and $W_B$ states on $A$ and $B$, respectively. The {\it maximally entangled state} $\Phi_{AB}:=\ket{\Phi}\bra{\Phi}_{AB}$ on $AB$ for $d:=d_A=d_B$ is not separable and defined via
\begin{align}
\text{$\ket{\Phi}_{AB}:=\frac{1}{\sqrt{d}}\sum_{x=1}^d\ket{x}_A\otimes\ket{x}_B$ for some orthonormal basis $\{\ket{x}\}_{x=1}^d$ of $\mathbb{C}^d$.}
\end{align}

The {\it swap operator} $F_{AB}$ on $A\otimes B$ exchanges the two quantum systems, i.e., $F_{AB}(W_A\otimes W_B)=W_B\otimes W_A$ for every state $W_A$ and $W_B$ on $A$ and $B$, respectively. {\it Classical-quantum states} are bipartite states that can be written in the form
\begin{align}
W_{XB}=\sum_{x=1}^{d_X}p_x\ket{x}\bra{x}_X\otimes W_B^x
\end{align}
for a probability distribution $\{p_x\}_{x=1}^{d_A}$, an orthonormal basis $\{\ket{x}_X\}_{x=1}^{d_X}$ of $\mathbb{C}^{d_X}$, and states $W_B^x$ on $B$ for $x=1,\dots,d_X$. We refer to $X$ as the classical part of the bipartite classical-quantum system $XB$.

{\it Quantum channels} (or in short {\it channels}) are linear maps $\mathcal{N}_{A\to B}:\mathcal{S}_A\to\mathcal{S}_B$ that are trace preserving and completely positive\footnote{A linear map $\mathcal{N}_{A\to B}:\mathcal{S}_A\to\mathcal{S}_B$ is said to be completely positive if $\mathcal{N}_{A\to B}\otimes \mathcal{I}_C$ is a positive map for every quantum system $C$, where $\mathcal{I}_C$ denotes the identity map on $\mathcal{S}_C$} (cp). In particular, they map states from the input system $A$ to states on the output system $B$. We often abbreviate bipartite channels $\mathcal{I}_A\otimes\mathcal{N}_B$ that act trivially on the $A$-system as $\mathcal{N}_B$, where $\mathcal{I}_A$ denotes the identity channel on $\mathcal{S}_A$. The partial trace $\mathrm{Tr}_B[\cdot]$ is a channel from $AB$ to $A$ defined via
\begin{align}
\mathrm{Tr}_B[\cdot]:=\sum_{x=1}^{d_B}\big(1_A\otimes\bra{x}_B\big)(\cdot)\big(1_A\otimes\ket{x}_B\big),
\end{align}
where $1_A$ denotes the identity matrix on $A$, and $\{\ket{x}\}_{x=1}^{d_B}$ an orthonormal basis of $\mathbb{C}^{d_B}$. For bipartite states $W_{AB}$, we write $W_A=\mathrm{Tr}_B[W_{AB}]$ for the reduced state on $A$. {\it Quantum measurements} (or in short {\it measurements}) are a special case of channels that can be written in the form

where $1_A$ denotes the identity matrix on $A$, and $\{\ket{x}\}_{x=1}^{d_B}$ an orthonormal basis of $\mathbb{C}^{d_B}$. For bipartite states $W_{AB}$, we write $W_A=\mathrm{Tr}_B[W_{AB}]$ for the reduced state on $A$. {\it Quantum measurements} (or in short {\it measurements}) are a special case of channels that can be written in the form
\begin{align}
\mathcal{M}_{A\to I}(\cdot):=\sum_{i\in I}\mathrm{Tr}\left[M_A^i(\cdot)\right]\ket{i}\bra{i}_I
\end{align}
with an orthonormal basis $\{\ket{i}_I\}_{i\in I}$ and $M_A^i\succeq0$ $\forall i\in I$ with $\sum_{i\in I}M_A^i=1_A$.

The distance between states is quantified by the metric induced from the Schatten one-norm $\|X\|_1:=\mathrm{Tr}\left[|X|\right]$. The distance between channels is quantified by the metric induced from the Diamond norm
\begin{align}
\|\mathcal{N}_{A\to B}\|_{\Diamond}:=\sup_{\|X\|_1\leq1}\|(\mathcal{N}_{A\to B}\otimes\mathcal{I}_A)(X_{AA})\|_1.
\end{align}

A multipartite state $W_{AB_1^n}$ on $AB_1^n\equiv AB_1\cdots B_n$ is called {\it symmetric with respect to $A$} if
\begin{align}
(\mathcal{I}_A\otimes\mathcal{U}_{B_1^n}^\pi)(W_{AB_1^n})=W_{AB_1^n}\quad\forall\pi\in\mathfrak{S}_n,
\end{align}
where $\mathfrak{S}_n$ denotes the symmetric group of $n$ elements and
\begin{align}
\mathcal{U}_{B_1^n}^\pi(W_{B_1}\otimes\cdots\otimes W_{B_n}):=W_{B_{\pi^{-1}(1)}}\otimes\cdots\otimes W_{B_{\pi^{-1}(n)}}.
\end{align}

