Now, to approximate the set of separable states within the set of bipartite states is a ubiquitous but hard problem in quantum information theory (see, e.g., \cite{Barak12}). Nevertheless, as realized in~\cite{Doherty04} the set of separable states can be approximated by the sum-of-squares hierarchies of Lasserre~\cite{Lasserre00} and Parrilo~\cite{Parrilo2003}. This lead to the {\it semidefinite programming hierarchy} of Doherty-Parrilo-Spedalieri (DPS), which is extensively employed to characterize quantum correlations in quantum information theory~\cite{Doherty02}. The underlying idea of the DPS hierarchy is that separable states $W_{AB}=\sum_i p_i W_A^i \otimes W_B^i$ on $A\otimes B$, where $\{p_i\}_{i\in I}$ is a probability distribution, are {\it $n$-extendible} to $W_{AB_1^n}=\sum_i p_iW_A^i \otimes (W_B^i)^{\otimes n}$ on $A\otimes B^{\otimes n}$ for any $n$, such that we have for any permutation $\pi$ that\footnote{Here and henceforth we use the notation $B_i^j$ to denote the systems $B_i\otimes\cdots\otimes B_j$, which should be interpreted as empty if $i>j$.}
\begin{align}
W_{AB_1^n}=\left(\mathcal{I}_A\otimes\mathcal{U}_{B_1^n}^\pi\right)(W_{AB_1^n})
\end{align}

\begin{lemma}\cite{brandao13b}\label{lem:conditioning-breaks-correlations}
Let $\rho_{A Z_1^n}$ be a classical-quantum state with the $Z_1^n$-systems classical and $\mathcal{U}^\pi_{Z_1^n}(\rho_{A Z_1^n})=\rho_{A Z_1^n}$ for all $\pi\in\mathfrak{S}_n$. Then, there exists $0\leq m < n$ such that
\begin{align}
\exc{z_{1}^{m}}{D(\rho_{AZ_{m+1}|z_1^m} \| \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m})} &\leq \frac{\log d_A}{n}
\end{align}
as well as
\begin{align}
\exc{z_{1}^{m}}{\| \rho_{AZ_{m+1}|z_1^m} - \rho_{A|z_1^m} \otimes \rho_{Z_{m+1}|z_1^m} \|_1^2} &\leq \frac{(2 \ln 2) \log d_A}{n},
\end{align}
where $\ln(\cdot)$ denotes the natural logarithm.
\end{lemma}

\begin{lemma}\cite{brandao13b}\label{lem:conditioning-breaks-correlations}
